-- test/mutants/MN30_comb_template.control.sql
-- THIS IS THE CONTROL: the same row update with the CORRECT template -- tree_sql_children's own
-- current output -- so applying it is a no-op UPDATE of the row MN30 corrupts. test/run_mutants.py
-- --verify applies it and requires MN30's expect_fail suites to PASS, which is what makes the
-- kill evidence about the planted edit rather than about the row being touched at all.
--
-- Hand-maintained, not generated by test/mutants/regen.py, for the same reason the mutant is:
-- there is no macro here for regen.py to extract from. Kept in sync with
-- tree_sql_children('{a}','{b}') by hand; test/sql/46_slot_registry.test's derivation gate
-- would catch drift the moment it diverged, since it compares this same row's template against
-- the macro called directly.
UPDATE tree_catalog.combinators
   SET template = '{b}._root = {a}._root AND {b}._parent = {a}._pre'
 WHERE op = 'child';
